long toSeconds(def raw) {
  if (raw == null) { return -1L; }
  String s = raw.toString().trim();
  if (s.length() < 2) { return -1L; }
  String unit = s.substring(s.length() - 1);
  String num = s.substring(0, s.length() - 1);
  for (int i = 0; i < num.length(); i++) { if (!Character.isDigit(num.charAt(i))) { return -1L; } }
  long n = Long.parseLong(num);
  if (unit == 's') { return n; }
  if (unit == 'm') { return n * 60L; }
  if (unit == 'h') { return n * 3600L; }
  if (unit == 'd') { return n * 86400L; }
  return -1L;
}
void addUnique(List list, def v) {
  if (v != null && v.toString() != '' && !list.contains(v.toString())) { list.add(v.toString()); }
}
String clip(def v, int n) {
  if (v == null) { return null; }
  String s = v.toString();
  return s.length() > n ? s.substring(0, n) : s;
}

Map raw = ctx.raw;
if (raw == null || !(raw instanceof Map)) { throw new IllegalArgumentException('missing raw rule'); }
if (ctx.rulescope == null) { ctx.rulescope = new HashMap(); }
Map r = new HashMap();

// Copied as they are.
for (String k : ['id', 'rule_id', 'name', 'enabled', 'type', 'language', 'severity', 'risk_score', 'tags',
                 'version', 'revision', 'author', 'license', 'created_at', 'updated_at', 'created_by',
                 'updated_by', 'max_signals', 'data_view_id', 'timestamp_override',
                 'timestamp_override_fallback_disabled']) {
  def v = raw.get(k);
  if (v != null && !(v instanceof String && ((String) v).trim() == '')) { r.put(k, v); }
}
if (r.name != null) { r.name = clip(r.name, 1024); }
r.interval_raw = raw.get('interval');
r.from_raw = raw.get('from');
r.building_block = raw.get('building_block_type') != null && raw.get('building_block_type').toString() != '';
r.prebuilt = raw.get('immutable') == true;
def rs = raw.get('rule_source');
if (rs instanceof Map) {
  r.source = ['type': rs.get('type'), 'is_customized': rs.get('is_customized')];
}

// Schedule. lookback_s is the whole window (from: now-6m is 360); additional is the part beyond the interval.
long interval = toSeconds(raw.get('interval'));
long lookback = -1L;
def from = raw.get('from');
if (from != null && from.toString().trim().startsWith('now-')) { lookback = toSeconds(from.toString().trim().substring(4)); }
if (interval > 0) { r.interval_s = interval; }
if (lookback > 0) { r.lookback_s = lookback; }
if (interval > 0 && lookback > 0) { r.additional_lookback_s = lookback - interval; }
r.schedule_parsed = interval > 0 && lookback > 0;

// Index patterns: remote ones (cluster:pattern) are kept apart for cross-cluster support.
List pats = new ArrayList();
List local = new ArrayList();
List remote = new ArrayList();
def idx = raw.get('index');
if (idx instanceof List) { for (def p : idx) { if (p != null && p.toString().trim() != '') { pats.add(p.toString().trim()); } } }
for (String p : pats) { if (p.contains(':')) { remote.add(p); } else { local.add(p); } }
if (!pats.isEmpty()) { r.index_patterns = pats; }
if (!local.isEmpty()) { r.index_patterns_local = local; r.index_patterns_csv = String.join(',', local); }
if (!remote.isEmpty()) { r.index_patterns_remote = remote; }
r.timestamp_field = r.get('timestamp_override') != null ? r.get('timestamp_override').toString() : '@timestamp';

// ATT&CK, flattened into multi-valued fields.
List fw = new ArrayList(); List tacId = new ArrayList(); List tacName = new ArrayList();
List tecId = new ArrayList(); List tecName = new ArrayList(); List subId = new ArrayList();
def threat = raw.get('threat');
if (threat instanceof List) {
  for (def t : threat) {
    if (!(t instanceof Map)) { continue; }
    addUnique(fw, t.get('framework'));
    def tac = t.get('tactic');
    if (tac instanceof Map) { addUnique(tacId, tac.get('id')); addUnique(tacName, tac.get('name')); }
    def techs = t.get('technique');
    if (techs instanceof List) {
      for (def te : techs) {
        if (!(te instanceof Map)) { continue; }
        addUnique(tecId, te.get('id')); addUnique(tecName, te.get('name'));
        def subs = te.get('subtechnique');
        if (subs instanceof List) { for (def su : subs) { if (su instanceof Map) { addUnique(subId, su.get('id')); } } }
      }
    }
  }
}
if (!fw.isEmpty() || !tacId.isEmpty()) {
  r.threat = ['framework': fw, 'tactic': ['id': tacId, 'name': tacName],
              'technique': ['id': tecId, 'name': tecName], 'subtechnique': ['id': subId]];
}

List integ = new ArrayList();
def ri = raw.get('related_integrations');
if (ri instanceof List) { for (def i : ri) { if (i instanceof Map) { addUnique(integ, i.get('package')); } } }
if (!integ.isEmpty()) { r.integrations = integ; }
List req = new ArrayList();
def rf = raw.get('required_fields');
if (rf instanceof List) { for (def f : rf) { if (f instanceof Map) { addUnique(req, f.get('name')); } } }
if (!req.isEmpty()) { r.required_fields = req; }

// The query itself isn't stored, only a hash that changes when it does.
def q = raw.get('query');
if (q != null && q.toString() != '') { r.query_hash = q.toString().sha256(); }

def es = raw.get('execution_summary');
if (es instanceof Map && es.get('last_execution') instanceof Map) {
  Map le = es.get('last_execution');
  Map lr = new HashMap();
  lr.date = le.get('date');
  lr.status = le.get('status');
  if (le.get('message') != null) { lr.message = clip(le.get('message'), 1024); }
  def m = le.get('metrics');
  if (m instanceof Map && m.get('total_search_duration_ms') != null) { lr.search_duration_ms = m.get('total_search_duration_ms'); }
  r.last_run = lr;
}

ctx.rulescope.rule = r;
ctx.remove('raw');
